SELECT COUNT(1) FROM public.iam_org_type_template
WHERE template_version = #{templateVersion} AND type_code = #{typeCode}
  AND status = 'PUBLISHED' AND is_deleted = false

SELECT request_hash, response_reference, status
FROM public.iam_idempotency_record
WHERE operator_type = 'PLATFORM_IDENTITY' AND operator_id = #{operatorId}
  AND operation_code = 'PLATFORM_TENANT_CREATE' AND idempotency_key_hash = #{keyHash}
  AND is_deleted = false
FOR UPDATE

mapper.update:
UPDATE public.iam_idempotency_record
SET status = 'COMPLETED', response_reference = #{responseReference}, updated_by = #{operatorId},
    updated_time = CURRENT_TIMESTAMP, version = version + 1
WHERE operator_type = 'PLATFORM_IDENTITY' AND operator_id = #{operatorId}
  AND operation_code = 'PLATFORM_TENANT_CREATE' AND idempotency_key_hash = #{keyHash}
  AND status = 'PROCESSING' AND is_deleted = false
